<?php

declare(strict_types=1);

namespace App\Agents\Calls;

use App\AgentRequests\Contracts\CallSender;
use App\AgentRequests\Support\CallKey;
use App\AgentRequests\Values\CallAccepted;
use App\Http\Data\Assignments\AssignmentResultData;

/**
 * The signed calls of Agents, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class AgentCalls
{
    public function __construct(private CallSender $sender) {}

    public function recordHeartbeat(
        CallKey $requestKey = new CallKey(),
    ): CallAccepted {
        return $this->sender->send(RecordHeartbeatCall::from([
            'requestKey' => $requestKey,
        ]));
    }

    public function retireAgent(
        string $agentId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(RetireAgentCall::from([
            'agentId' => $agentId,
            'requestKey' => $requestKey,
        ]));
    }
}
